package com.coffeesaerosmp.auth.auth;

import java.nio.charset.StandardCharsets;
import java.util.UUID;

public final class UUIDUtil {

    private UUIDUtil() {}

    /**
     * Mojang-authenticated UUIDs are version 4 (randomly generated by Mojang).
     * Vanilla offline UUIDs are version 3 (MD5 of "OfflinePlayer:" + name).
     * When behind Velocity + AuthVelocity, premium players keep their real v4 UUID
     * and cracked players get their deterministic v3 UUID on the backend.
     */
    public static boolean isPremiumUUID(UUID uuid) {
        return uuid.version() == 4;
    }

    /**
     * Compute what offline UUID vanilla would assign for a given username.
     * Used to verify that an offline player's UUID matches their claimed username
     * and has not been spoofed.
     */
    public static UUID expectedOfflineUUID(String username) {
        return UUID.nameUUIDFromBytes(
            ("OfflinePlayer:" + username).getBytes(StandardCharsets.UTF_8)
        );
    }
}
